/**
 * Graphs the tutor draws for the student.
 *
 * When a student asks to see a graph ("can you draw it?", "show me the
 * graph"), the server picks a diagram and sends its description to the
 * browser, which draws it inside the tutor's reply. Nothing is generated by
 * the language model: the lines come from the problem's own equations when it
 * is a linear supply and demand problem, and from a fixed textbook template
 * otherwise, so the picture is always economically correct.
 *
 * A spec uses a unit square, x to the right and y up:
 *   { title, xLabel, yLabel,
 *     lines:  [{ label, pts: [[x, y], ...], color, dashed? }],
 *     guides: [{ x, y, xText?, yText? }],      dotted drop-lines to the axes
 *     areas:  [{ pts, label }],                shaded regions
 *     ticks:  [{ axis: 'x' | 'y', at, text }], numbers on the axes
 *     caption }
 */

import { findCurves, findTax, fmt } from './econSolver.js'

const DRAW_RE = [
  /\b(draw|sketch|plot|illustrate|visuali[sz]e|diagram)\b/i,
  /\b(show|give|make|see)\b[^.?!]{0,40}\b(graph|picture|chart|curves?)\b/i,
  /\bgraph\s+(it|this|that|one|for me)\b/i,
  /\bwhat (does|do|would|should)\b[^.?!]{0,40}\b(graph|curves?)\b[^.?!]{0,12}\blook/i,
]

/** True when the student is asking to see a graph. */
export function wantsGraph(text) {
  const t = String(text || '')
  return DRAW_RE.some((re) => re.test(t))
}

const BLUE = 'blue'
const RED = 'red'
const round = (v) => Math.round(v * 1000) / 1000

// ── Templates (no numbers) ──────────────────────────────────────────────────

function marketBase({ xLabel = 'Quantity', yLabel = 'Price', d = 'D', s = 'S' } = {}) {
  return {
    xLabel,
    yLabel,
    lines: [
      { label: d, pts: [[0.1, 0.9], [0.9, 0.1]], color: BLUE },
      { label: s, pts: [[0.1, 0.1], [0.9, 0.9]], color: RED },
    ],
    guides: [],
    areas: [],
    ticks: [],
  }
}

const TEMPLATES = {
  supply_demand() {
    const g = marketBase()
    g.title = 'Supply and demand'
    g.guides.push({ x: 0.5, y: 0.5, xText: 'Q*', yText: 'P*' })
    g.caption = 'Equilibrium is where the two curves cross.'
    return g
  },
  price_ceiling() {
    const g = marketBase()
    g.title = 'Price ceiling'
    g.lines.push({ label: 'Ceiling', pts: [[0, 0.3], [0.95, 0.3]], color: 'green', dashed: true })
    g.guides.push({ x: 0.3, y: 0.3, xText: 'Qs' }, { x: 0.7, y: 0.3, xText: 'Qd' }, { x: 0.5, y: 0.5, yText: 'P*' })
    g.caption = 'Below equilibrium, buyers want more (Qd) than sellers offer (Qs): a shortage.'
    return g
  },
  price_floor() {
    const g = marketBase()
    g.title = 'Price floor'
    g.lines.push({ label: 'Floor', pts: [[0, 0.7], [0.95, 0.7]], color: 'green', dashed: true })
    g.guides.push({ x: 0.3, y: 0.7, xText: 'Qd' }, { x: 0.7, y: 0.7, xText: 'Qs' }, { x: 0.5, y: 0.5, yText: 'P*' })
    g.caption = 'Above equilibrium, sellers offer more (Qs) than buyers want (Qd): a surplus.'
    return g
  },
  minimum_wage() {
    const g = marketBase({ xLabel: 'Workers', yLabel: 'Wage', d: 'Labor demand', s: 'Labor supply' })
    g.title = 'Minimum wage'
    g.lines.push({ label: 'Minimum wage', pts: [[0, 0.7], [0.95, 0.7]], color: 'green', dashed: true })
    g.guides.push({ x: 0.3, y: 0.7, xText: 'Hired' }, { x: 0.7, y: 0.7, xText: 'Want work' }, { x: 0.5, y: 0.5, yText: 'W*' })
    g.caption = 'Above the equilibrium wage, more people want work than firms hire: unemployment.'
    return g
  },
  tax() {
    const g = marketBase()
    g.title = 'Per-unit tax on sellers'
    g.lines.push({ label: 'S + tax', pts: [[0.1, 0.3], [0.7, 0.9]], color: RED, dashed: true })
    g.guides.push({ x: 0.4, y: 0.6, xText: 'Qt', yText: 'Pb' }, { x: 0.4, y: 0.4, yText: 'Ps' }, { x: 0.5, y: 0.5, xText: 'Q*' })
    g.areas.push({ pts: [[0.4, 0.6], [0.5, 0.5], [0.4, 0.4]], label: 'DWL' })
    g.caption = 'The tax drives a wedge between what buyers pay (Pb) and what sellers keep (Ps).'
    return g
  },
  demand_shift() {
    const g = marketBase({ d: 'D1' })
    g.title = 'Increase in demand'
    g.lines.push({ label: 'D2', pts: [[0.3, 0.95], [0.95, 0.3]], color: BLUE, dashed: true })
    g.guides.push({ x: 0.5, y: 0.5, xText: 'Q1', yText: 'P1' }, { x: 0.625, y: 0.625, xText: 'Q2', yText: 'P2' })
    g.caption = 'Demand shifts right: both the price and the quantity rise.'
    return g
  },
  supply_shift() {
    const g = marketBase({ s: 'S1' })
    g.title = 'Increase in supply'
    g.lines.push({ label: 'S2', pts: [[0.3, 0.05], [0.95, 0.7]], color: RED, dashed: true })
    g.guides.push({ x: 0.5, y: 0.5, xText: 'Q1', yText: 'P1' }, { x: 0.625, y: 0.375, xText: 'Q2', yText: 'P2' })
    g.caption = 'Supply shifts right: the price falls and the quantity rises.'
    return g
  },
  monopoly() {
    return {
      title: 'Monopoly',
      xLabel: 'Quantity',
      yLabel: 'Price, cost',
      lines: [
        { label: 'D', pts: [[0.05, 0.9], [0.9, 0.05]], color: BLUE },
        { label: 'MR', pts: [[0.05, 0.9], [0.475, 0.05]], color: 'purple' },
        { label: 'MC', pts: [[0.05, 0.2], [0.9, 0.7]], color: RED },
      ],
      guides: [{ x: 0.32, y: 0.63, xText: 'Qm', yText: 'Pm' }, { x: 0.32, y: 0.359 }],
      areas: [],
      ticks: [],
      caption: 'Find Qm where MR = MC, then go up to the demand curve for the price Pm.',
    }
  },
  ppf() {
    const pts = []
    for (let i = 0; i <= 24; i++) {
      const a = (Math.PI / 2) * (i / 24)
      pts.push([round(0.88 * Math.sin(a)), round(0.88 * Math.cos(a))])
    }
    return {
      title: 'Production possibilities frontier',
      xLabel: 'Good X',
      yLabel: 'Good Y',
      lines: [{ label: 'PPF', pts, color: BLUE }],
      guides: [],
      areas: [],
      ticks: [],
      points: [
        { x: 0.62, y: 0.62, text: 'A: efficient' },
        { x: 0.35, y: 0.35, text: 'B: inefficient' },
        { x: 0.82, y: 0.8, text: 'C: out of reach' },
      ],
      caption: 'Points on the curve use every resource. Moving along it trades one good for the other.',
    }
  },
}

function templateFor(text) {
  const t = String(text || '').toLowerCase()
  if (/monopol|marginal revenue|\bmr\b/.test(t)) return 'monopoly'
  if (/\bppf\b|production possibilit|opportunity cost/.test(t)) return 'ppf'
  if (/minimum wage|wage floor/.test(t)) return 'minimum_wage'
  if (/ceiling|rent control|price cap/.test(t)) return 'price_ceiling'
  if (/price floor|\bfloor\b/.test(t)) return 'price_floor'
  if (/\btax/.test(t)) return 'tax'
  if (/demand\s+(increase|rise|shift|go|grow)|(increase|rise|shift) in demand/.test(t)) return 'demand_shift'
  if (/supply\s+(increase|rise|shift|go|grow)|(increase|rise|shift) in supply/.test(t)) return 'supply_shift'
  if (/supply|demand|equilibrium|market|price|quantity/.test(t)) return 'supply_demand'
  return null
}

// ── The problem's own numbers ───────────────────────────────────────────────

/**
 * Supply and demand drawn to scale from Qd = a + bP and Qs = c + dP.
 * `showAnswer` puts the equilibrium numbers on the axes; without it the
 * crossing is only marked P* and Q*, so the picture does not solve the problem.
 */
function numericMarket(demand, supply, { tax = null, showAnswer = false } = {}) {
  const { a, b } = demand
  const { a: c, b: d } = supply
  if (!(b < 0) || !(d > 0) || !(a > 0)) return null
  const P = (a - c) / (d - b)
  const Q = a + b * P
  if (!(P > 0) || !(Q > 0)) return null
  const pTop = -a / b // demand hits the price axis
  const pMax = pTop * 1.1
  // Keep the crossing near the middle: a long demand tail would squeeze it into a corner.
  const qEnd = Math.min(a, Q * 2.1)
  const qMax = qEnd * 1.08
  const X = (q) => round(Math.max(0, Math.min(1, q / qMax)))
  const Y = (p) => round(Math.max(0, Math.min(1, p / pMax)))

  /** Supply-style line Q = c0 + d*P, clipped to the visible box. */
  const rising = (c0) => {
    const pLow = Math.max(0, -c0 / d)
    let pHigh = pTop
    if (c0 + d * pHigh > qEnd) pHigh = (qEnd - c0) / d
    return [[X(c0 + d * pLow), Y(pLow)], [X(c0 + d * pHigh), Y(pHigh)]]
  }

  const g = {
    title: tax ? 'Supply and demand with the tax' : 'Supply and demand for this problem',
    xLabel: 'Quantity',
    yLabel: 'Price',
    lines: [
      { label: 'D', pts: [[X(0), Y(pTop)], [X(qEnd), Y((qEnd - a) / b)]], color: BLUE },
      { label: 'S', pts: rising(c), color: RED },
    ],
    guides: [{ x: X(Q), y: Y(P), xText: showAnswer ? `Q* = ${fmt(Q)}` : 'Q*', yText: showAnswer ? `P* = ${fmt(P)}` : 'P*' }],
    areas: [],
    ticks: [{ axis: 'y', at: Y(pTop), text: fmt(pTop) }],
    caption: 'Drawn to scale from the two equations. The curves cross at the equilibrium.',
  }
  if (qEnd === a) g.ticks.push({ axis: 'x', at: X(a), text: fmt(a) })
  if (c < 0) g.ticks.push({ axis: 'y', at: Y(-c / d), text: fmt(-c / d) })

  if (tax && tax > 0) {
    const Pb = (a - c + d * tax) / (d - b)
    const Ps = Pb - tax
    const Qt = a + b * Pb
    if (Qt > 0 && Ps > 0) {
      g.lines.push({ label: 'S + tax', pts: rising(c - d * tax), color: RED, dashed: true })
      g.guides.push(
        { x: X(Qt), y: Y(Pb), xText: showAnswer ? `Qt = ${fmt(Qt)}` : 'Qt', yText: showAnswer ? `Pb = ${fmt(Pb)}` : 'Pb' },
        { x: X(Qt), y: Y(Ps), yText: showAnswer ? `Ps = ${fmt(Ps)}` : 'Ps' }
      )
      g.areas.push({ pts: [[X(Qt), Y(Pb)], [X(Q), Y(P)], [X(Qt), Y(Ps)]], label: 'DWL' })
      g.caption = `The $${fmt(tax)} tax shifts supply up. Buyers pay Pb, sellers keep Ps, and the quantity falls to Qt.`
    }
  }
  return g
}

/**
 * Pick the graph to draw, or null when the student did not ask for one.
 *   studentText  what the student typed or said
 *   problem      the problem statement (OCR of the pasted screenshot)
 *   workText     the transcript of their handwriting
 *   showAnswer   true when their work already shows the final answer
 */
export function graphForRequest({ studentText, problem = '', workText = '', showAnswer = false } = {}) {
  if (!wantsGraph(studentText)) return null
  const context = `${problem}\n${workText}`
  const asked = templateFor(studentText)
  // The equations in the problem give a to-scale market graph, unless they asked for another kind.
  if (!asked || ['supply_demand', 'tax'].includes(asked)) {
    let { demand, supply } = findCurves(problem)
    if (!demand || !supply) {
      const w = findCurves(workText)
      demand = demand || w.demand
      supply = supply || w.supply
    }
    if (demand && supply) {
      const t = findTax(problem) ?? findTax(workText)
      const wantsTax = asked === 'tax' || /\btax|new one|after/i.test(String(studentText))
      const g = numericMarket(demand, supply, { tax: wantsTax ? t : null, showAnswer })
      if (g) return g
    }
  }
  const kind = asked || templateFor(context) || 'supply_demand'
  return TEMPLATES[kind]()
}

/** One sentence for the model about what was just drawn. */
export function describeDrawnGraph(g) {
  const curves = g.lines.map((l) => l.label).join(', ')
  return `A graph titled "${g.title}" has just been drawn for the student inside your reply (curves: ${curves}; axes: ${g.yLabel} and ${g.xLabel}). Do not say you cannot draw. In 1 or 2 short sentences, tell them what to look at on it. Do not state final numbers.`
}
